-- new object type path: SCHEMA_EXPORT/PROCEDURE/PROCEDURE
-- CONNECT GXCONTABLE
CREATE PROCEDURE            SP_CARGA_INT_EXIST_CTRL_AMER
AS
BEGIN

    -------------------------------------------------------------------------
    -- 1. COPIAR A ORACLE LOS EVENTOS PENDIENTES DE AMERICA
    --
    -- Procesado = 0 en AMERICA significa:
    -- "El evento todavia no fue confirmado como recibido por Oracle".
    --
    -- Ademas de CambioId se guarda una copia local de todos los datos
    -- del evento que necesitaran los procedimientos posteriores.
    -------------------------------------------------------------------------
    INSERT INTO GXCONTABLE.INTEGRACIONEXISTCONTROL
    (
        IECCAMBIOID,

        IECTIPOOPERACION,
        IECPRODUC,
        IECDEPO,
        IECUBI,

        IECCANTIREALANTERIOR,
        IECCANTIREALNUEVO,

        IECCOMPROCODI,
        IECCOMPRONUME,
        IECCOMPROLINEA,
        IECCOMPROFECHA,
        IECFECHACAMBIO,

        IECEXISTENCIASPROCESADAS,
        IECDETALLEPROCESADO,

        IECERROREXISTENCIASMENSAJE,
        IECERRORDETALLEMENSAJE,

        IECFCHALTA,
        IECFCHULTIMOPROCESO,

        IECTIPOMOVIMIENTODETALLE
    )
    SELECT
        R."CambioId",

        RTRIM(R."TipoOperacion"),
        R."Produc",
        R."Depo",
        R."Ubi",

        R."CantiRealAnterior",
        R."CantiRealNuevo",

        RTRIM(R."ComproCodi"),
        R."ComproNume",
        R."ComproLinea",
        R."ComproFecha",
        R."FechaCambio",

        0,
        0,

        NULL,
        NULL,

        SYSDATE,
        NULL,

        NULL

    FROM dbo.IntegracionExistencias@MSSQL R

    WHERE R."Procesado" = 0

      AND NOT EXISTS
      (
          SELECT 1
          FROM GXCONTABLE.INTEGRACIONEXISTCONTROL C
          WHERE C.IECCAMBIOID = R."CambioId"
      );


    -------------------------------------------------------------------------
    -- 2. CONFIRMAR PRIMERO LA COPIA LOCAL
    --
    -- Este COMMIT es deliberado.
    --
    -- A partir de este punto los eventos ya estan seguros en Oracle.
    -- Si posteriormente falla el UPDATE hacia AMERICA, en la siguiente
    -- ejecucion NOT EXISTS impedira duplicarlos y se volvera a intentar
    -- solamente la confirmacion remota.
    -------------------------------------------------------------------------
    COMMIT;


    -------------------------------------------------------------------------
    -- 3. ACK HACIA AMERICA
    --
    -- Buscar solamente eventos que:
    --
    --   a) AMERICA todavia tiene con Procesado = 0
    --   b) ya existen efectivamente en INTEGRACIONEXISTCONTROL
    --
    -- Se actualiza por CambioId exacto para no marcar accidentalmente
    -- movimientos que hayan aparecido concurrentemente.
    -------------------------------------------------------------------------
    FOR R_ACK IN
    (
        SELECT
            R."CambioId" AS CAMBIOID

        FROM dbo.IntegracionExistencias@MSSQL R

        WHERE R."Procesado" = 0

          AND EXISTS
          (
              SELECT 1
              FROM GXCONTABLE.INTEGRACIONEXISTCONTROL C
              WHERE C.IECCAMBIOID = R."CambioId"
          )
    )
    LOOP

        UPDATE dbo.IntegracionExistencias@MSSQL
           SET "Procesado" = 1
         WHERE "CambioId" = R_ACK.CAMBIOID
           AND "Procesado" = 0;

    END LOOP;


    -------------------------------------------------------------------------
    -- 4. CONFIRMAR LOS ACK REALIZADOS EN AMERICA
    -------------------------------------------------------------------------
    COMMIT;


EXCEPTION

    WHEN OTHERS THEN

        ---------------------------------------------------------------------
        -- Si falla antes del primer COMMIT:
        --     no queda nada insertado en Oracle.
        --
        -- Si falla despues del primer COMMIT:
        --     Oracle ya conserva los eventos y solamente se revierten
        --     los ACK remotos pendientes.
        --
        -- La proxima ejecucion recupera naturalmente ambos casos.
        ---------------------------------------------------------------------
        ROLLBACK;

        RAISE;

END; 
/
CREATE PROCEDURE SP_CLASIF_MOV_DET_AMER
AS
BEGIN

    MERGE INTO GXCONTABLE.INTEGRACIONEXISTCONTROL C
    USING
    (
        SELECT
            X.CambioId,
            X.TipoMovimientoDetalle
        FROM
        (
            SELECT
                Q.CambioId,

                CASE

                    ---------------------------------------------------------
                    -- 1. TRANSFERENCIA
                    ---------------------------------------------------------
                    WHEN Q.TieneTransferencia = 1
                     AND Q.TieneBajaProducto = 1
                     AND Q.TieneAltaProducto = 1
                    THEN 'T'

                    ---------------------------------------------------------
                    -- 2. DEVOLUCION
                    ---------------------------------------------------------
                    WHEN Q.TieneDevstGrupo = 1
                     AND Q.TieneAltaGrupo = 1
                    THEN 'DV'

                    ---------------------------------------------------------
                    -- 3. INGRESO
                    ---------------------------------------------------------
                    WHEN Q.TieneIngresoGrupo = 1
                     AND Q.TieneAltaGrupo = 1
                    THEN 'I'

                    ---------------------------------------------------------
                    -- 4. EGRESO
                    ---------------------------------------------------------
                    WHEN Q.EsBajaFila = 1
                    THEN 'E'

                    ELSE NULL

                END AS TipoMovimientoDetalle

            FROM
            (
                SELECT
                    R."CambioId" AS CambioId,

                    ---------------------------------------------------------
                    -- PRODUCTO CON COMPROBANTE DE TRANSFERENCIA
                    ---------------------------------------------------------
                    MAX
                    (
                        CASE
                            WHEN RTRIM(R."ComproCodi") IN
                            (
                                'R1090','R1080','R1070','R1050',
                                'R1030','R1060','R1010','R1040',
                                'R9010','R8010','R7010','R5010',
                                'R3010','R6010','R4010','R1001',

                                'S1090','S1080','S1070','S1050',
                                'S1030','S1060','S1040','S1010',
                                'S9010','S8010','S7010','S5010',
                                'S3010','S6010','S4010','S1001',

                                '1C1','1C2','1C3','TST1'
                            )
                            THEN 1
                            ELSE 0
                        END
                    )
                    OVER
                    (
                        PARTITION BY R."Produc"
                    ) AS TieneTransferencia,

                    ---------------------------------------------------------
                    -- PRODUCTO CON BAJA
                    ---------------------------------------------------------
                    MAX
                    (
                        CASE
                            WHEN RTRIM(R."TipoOperacion") = 'D'
                              OR
                              (
                                  RTRIM(R."TipoOperacion") = 'U'
                                  AND NVL(R."CantiRealNuevo", 0)
                                      < NVL(R."CantiRealAnterior", 0)
                              )
                            THEN 1
                            ELSE 0
                        END
                    )
                    OVER
                    (
                        PARTITION BY R."Produc"
                    ) AS TieneBajaProducto,

                    ---------------------------------------------------------
                    -- PRODUCTO CON ALTA
                    ---------------------------------------------------------
                    MAX
                    (
                        CASE
                            WHEN RTRIM(R."TipoOperacion") = 'I'
                              OR
                              (
                                  RTRIM(R."TipoOperacion") = 'U'
                                  AND NVL(R."CantiRealNuevo", 0)
                                      > NVL(R."CantiRealAnterior", 0)
                              )
                            THEN 1
                            ELSE 0
                        END
                    )
                    OVER
                    (
                        PARTITION BY R."Produc"
                    ) AS TieneAltaProducto,

                    ---------------------------------------------------------
                    -- GRUPO Produc + Depo + Ubi CON ALTA
                    ---------------------------------------------------------
                    MAX
                    (
                        CASE
                            WHEN RTRIM(R."TipoOperacion") = 'I'
                              OR
                              (
                                  RTRIM(R."TipoOperacion") = 'U'
                                  AND NVL(R."CantiRealNuevo", 0)
                                      > NVL(R."CantiRealAnterior", 0)
                              )
                            THEN 1
                            ELSE 0
                        END
                    )
                    OVER
                    (
                        PARTITION BY
                            R."Produc",
                            R."Depo",
                            R."Ubi"
                    ) AS TieneAltaGrupo,

                    ---------------------------------------------------------
                    -- GRUPO CON DEVST
                    ---------------------------------------------------------
                    MAX
                    (
                        CASE
                            WHEN RTRIM(R."ComproCodi") = 'DEVST'
                            THEN 1
                            ELSE 0
                        END
                    )
                    OVER
                    (
                        PARTITION BY
                            R."Produc",
                            R."Depo",
                            R."Ubi"
                    ) AS TieneDevstGrupo,

                    ---------------------------------------------------------
                    -- GRUPO CON COMPROBANTE DE INGRESO
                    ---------------------------------------------------------
                    MAX
                    (
                        CASE
                            WHEN RTRIM(R."ComproCodi") IN
                            (
                                'ISSI',
                                'INGEM',
                                'INGSI',
                                'ISCOC',
                                'ISFCP',
                                'INNGR',
                                'IREMA'
                            )
                            THEN 1
                            ELSE 0
                        END
                    )
                    OVER
                    (
                        PARTITION BY
                            R."Produc",
                            R."Depo",
                            R."Ubi"
                    ) AS TieneIngresoGrupo,

                    ---------------------------------------------------------
                    -- ESTA FILA ES UNA BAJA
                    ---------------------------------------------------------
                    CASE
                        WHEN RTRIM(R."TipoOperacion") = 'D'
                          OR
                          (
                              RTRIM(R."TipoOperacion") = 'U'
                              AND NVL(R."CantiRealNuevo", 0)
                                  < NVL(R."CantiRealAnterior", 0)
                          )
                        THEN 1
                        ELSE 0
                    END AS EsBajaFila

                FROM dbo.IntegracionExistencias@MSSQL R

                INNER JOIN GXCONTABLE.INTEGRACIONEXISTCONTROL C0
                    ON C0.IECCambioId = R."CambioId"

                WHERE NVL(C0.IECDetalleProcesado, 0) = 0

            ) Q

        ) X

        WHERE X.TipoMovimientoDetalle IS NOT NULL

    ) S

    ON
    (
        C.IECCambioId = S.CambioId
    )

    WHEN MATCHED THEN
        UPDATE SET
            C.IECTIPOMOVIMIENTODETALLE = S.TipoMovimientoDetalle,
            C.IECFchUltimoProceso       = SYSDATE

        WHERE NVL(C.IECDetalleProcesado, 0) = 0
          AND C.IECTIPOMOVIMIENTODETALLE IS NULL;


    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;

END; 
/
CREATE PROCEDURE SP_PROCESAR_DEVOLUCIONES_AMER
AS
    v_cantidad       NUMBER;
    v_error          VARCHAR2(1000);
    v_devolucion_id  NUMBER;
    v_deposito_id    NUMBER;
    v_disponibles    NUMBER;

BEGIN

    -------------------------------------------------------------------------
    -- LIMPIAR DATOS TEMPORALES DE UNA EJECUCION ANTERIOR
    -------------------------------------------------------------------------
    DELETE FROM TMP_UNID_DV;
    DELETE FROM TMP_CAB_DV;
    DELETE FROM TMP_ESTADO_AMER;
    DELETE FROM TMP_PROD_DV;
    DELETE FROM TMP_GRUPOS_DV;
    DELETE FROM TMP_INT_DV;
    DELETE FROM TMP_PEND_DV;

    COMMIT;


    -------------------------------------------------------------------------
    -- 1. CAMBIOS DV PENDIENTES
    -------------------------------------------------------------------------
    INSERT INTO TMP_PEND_DV
    (
        CAMBIOID
    )
    SELECT
        C.IECCAMBIOID
    FROM INTEGRACIONEXISTCONTROL C
    WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0
      AND C.IECTIPOMOVIMIENTODETALLE = 'DV';


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_PEND_DV;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    /*
       Dejamos confirmada TMP_PEND_DV para que sobreviva
       a un eventual ROLLBACK posterior.
    */
    COMMIT;


    -------------------------------------------------------------------------
    -- 2. TRAER CAMBIOS DESDE AMERICA / SQL SERVER
    -------------------------------------------------------------------------
    INSERT INTO TMP_INT_DV
    (
        CAMBIOID,
        PRODUC,
        DEPO,
        UBI,
        COMPRONUME,
        COMPROCodi,
        CANTIREALANTERIOR,
        CANTIREALNUEVO
    )
    SELECT
        R."CambioId",
        R."Produc",

        NVL(
            R."Depo",
            CHR(1)
        ),

        NVL(
            R."Ubi",
            CHR(1)
        ),

        R."ComproNume",
        RTRIM(R."ComproCodi"),
        R."CantiRealAnterior",
        R."CantiRealNuevo"

    FROM dbo.IntegracionExistencias@MSSQL R

    INNER JOIN TMP_PEND_DV P
        ON P.CAMBIOID = R."CambioId";


    -------------------------------------------------------------------------
    -- 3. GRUPOS FINOS:
    --    PRODUCTO + DEPOSITO + UBICACION
    -------------------------------------------------------------------------
    INSERT INTO TMP_GRUPOS_DV
    (
        PRODUC,
        DEPO,
        UBI,
        COMPRONUMEDEVST,
        CANTIDADDEVUELTA
    )
    SELECT
        PRODUC,
        DEPO,
        UBI,

        MAX
        (
            CASE
                WHEN RTRIM(COMPROCodi) = 'DEVST'
                THEN NVL(COMPRONUME, 0)
                ELSE 0
            END
        ),

        TRUNC
        (
            SUM
            (
                CASE
                    WHEN NVL(CANTIREALNUEVO, 0)
                       > NVL(CANTIREALANTERIOR, 0)
                    THEN
                        NVL(CANTIREALNUEVO, 0)
                        -
                        NVL(CANTIREALANTERIOR, 0)

                    ELSE 0
                END
            )
        )

    FROM TMP_INT_DV

    GROUP BY
        PRODUC,
        DEPO,
        UBI

    HAVING

        SUM
        (
            CASE
                WHEN RTRIM(COMPROCodi) = 'DEVST'
                THEN 1
                ELSE 0
            END
        ) > 0

        AND

        MAX
        (
            CASE
                WHEN RTRIM(COMPROCodi) = 'DEVST'
                THEN NVL(COMPRONUME, 0)
                ELSE 0
            END
        ) > 0

        AND

        SUM
        (
            CASE
                WHEN NVL(CANTIREALNUEVO, 0)
                   > NVL(CANTIREALANTERIOR, 0)
                THEN
                    NVL(CANTIREALNUEVO, 0)
                    -
                    NVL(CANTIREALANTERIOR, 0)

                ELSE 0
            END
        ) > 0;


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_GRUPOS_DV;


    -------------------------------------------------------------------------
    -- NO SE PUDO ARMAR NINGUN GRUPO DV
    -------------------------------------------------------------------------
    IF v_cantidad = 0 THEN

        UPDATE INTEGRACIONEXISTCONTROL C
           SET C.IECERRORDETALLEMENSAJE =
               'No se pudo armar grupo DV con DEVST y cantidad devuelta mayor a 0',

               C.IECFCHULTIMOPROCESO = SYSDATE

         WHERE EXISTS
         (
             SELECT 1
             FROM TMP_PEND_DV P
             WHERE P.CAMBIOID = C.IECCAMBIOID
         );

        COMMIT;

        RETURN;

    END IF;


    -------------------------------------------------------------------------
    -- 4. PRODUCTOS DE LA DEVOLUCION
    -------------------------------------------------------------------------
    INSERT INTO TMP_PROD_DV
    (
        COMPRONUMEDEVST,
        PRODUC,
        CANTIDADPRODUCTO,
        PRODUCTOSID,
        PRODUCTOSUNIDADMEDIDA,
        DEVOLUCIONPRODUCTOID
    )
    SELECT
        G.COMPRONUMEDEVST,
        G.PRODUC,
        SUM(G.CANTIDADDEVUELTA),

        P.PRODUCTOSID,

        UM.UNIDADESMEDIDACODIGO,

        NULL

    FROM TMP_GRUPOS_DV G

    LEFT JOIN PRODUCTOS P
        ON P.PRODUCTOSCODIGO = G.PRODUC

    LEFT JOIN UNIDADESMEDIDA UM
        ON UM.UNIDADESMEDIDAID = P.UNIDADESMEDIDAID

    GROUP BY
        G.COMPRONUMEDEVST,
        G.PRODUC,
        P.PRODUCTOSID,
        UM.UNIDADESMEDIDACODIGO;


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_PROD_DV
     WHERE PRODUCTOSID IS NULL;


    IF v_cantidad > 0 THEN
        RAISE_APPLICATION_ERROR
        (
            -20001,
            'Hay productos DV que no existen en Productos local'
        );
    END IF;


    -------------------------------------------------------------------------
    -- 5. ESTADO ACTUAL DE AMERICA
    -------------------------------------------------------------------------
    INSERT INTO TMP_ESTADO_AMER
    (
        PRODUC,
        DEPO,
        UBI,
        DESCRIP,
        CANTIDAD,
        DEPOSITODESCR,
        COSTOULTICOMPRA,
        FCHULTICOMPRA,
        CUENTA
    )
    SELECT
        DET."produc",

        NVL(
            DET."depo",
            CHR(1)
        ),

        NVL(
            DET."ubi",
            CHR(1)
        ),

        REPLACE(
            P."descrip_larga",
            ';',
            ' '
        ),

        DET."canti_real",
        D."descrip",
        P."costo_ulti_compra",
        P."fecha_ulti_compra",
        P."cuenta"

    FROM dbo.produc_deta@MSSQL DET

    INNER JOIN dbo.productos@MSSQL P
        ON P."produc" = DET."produc"

    INNER JOIN dbo.depositos@MSSQL D
        ON D."depo" = DET."depo"

    INNER JOIN TMP_GRUPOS_DV G
        ON G.PRODUC = DET."produc"

       AND G.DEPO =
           NVL(
               DET."depo",
               CHR(1)
           )

       AND G.UBI =
           NVL(
               DET."ubi",
               CHR(1)
           );


    /*
       Confirmamos solamente las tablas temporales.

       A partir de acá comienza conceptualmente la transaccion
       del procedimiento original.
    */
    COMMIT;


    -------------------------------------------------------------------------
    -- 6. ACTUALIZAR / INSERTAR EXISTENCIAS
    -------------------------------------------------------------------------
    MERGE INTO EXISTENCIAS E

    USING TMP_ESTADO_AMER A

    ON
    (
           E.EXISTENCIASPRODUCTOCODI = A.PRODUC

       AND NVL(
               E.EXISTENCIASDEPOSITOCODI,
               CHR(1)
           ) = A.DEPO

       AND NVL(
               E.EXISTENCIASUBICACIONCODI,
               CHR(1)
           ) = A.UBI
    )

    WHEN MATCHED THEN
        UPDATE SET

            E.EXISTENCIASPRODUCTODESCR =
                A.DESCRIP,

            E.EXISTENCIASCANTIDAD =
                A.CANTIDAD,

            E.EXISTENCIASDEPOSITODESCR =
                A.DEPOSITODESCR,

            E.EXISTENCIASCOSTOULTICOMPRA =
                A.COSTOULTICOMPRA,

            E.EXISTENCIASFCHULTICOMPRA =
                A.FCHULTICOMPRA,

            E.EXISTENCIASCUENTACODI =
                A.CUENTA


    WHEN NOT MATCHED THEN
        INSERT
        (
            EXISTENCIASPRODUCTOCODI,
            EXISTENCIASPRODUCTODESCR,
            EXISTENCIASCANTIDAD,
            EXISTENCIASDEPOSITOCODI,
            EXISTENCIASDEPOSITODESCR,
            EXISTENCIASUBICACIONCODI,
            EXISTENCIASCOSTOULTICOMPRA,
            EXISTENCIASFCHULTICOMPRA,
            EXISTENCIASCUENTACODI
        )
        VALUES
        (
            A.PRODUC,
            NULLIF(A.DESCRIP, CHR(1)),
            A.CANTIDAD,
            NULLIF(A.DEPO, CHR(1)),
            A.DEPOSITODESCR,
            NULLIF(A.UBI, CHR(1)),
            A.COSTOULTICOMPRA,
            A.FCHULTICOMPRA,
            A.CUENTA
        );


    -------------------------------------------------------------------------
    -- 7. CREAR CABECERA DEVOLUCION
    --    UNA POR COMPRONUME DEVST
    -------------------------------------------------------------------------
    FOR CAB IN
    (
        SELECT DISTINCT
            COMPRONUMEDEVST
        FROM TMP_PROD_DV
        ORDER BY COMPRONUMEDEVST
    )
    LOOP

        INSERT INTO DEVOLUCION
        (
            DEVOLUCIONESTADO,
            DEVOLUCIONFCHALTA
        )
        VALUES
        (
            'P',
            SYSDATE
        )
        RETURNING DEVOLUCIONID
             INTO v_devolucion_id;


        INSERT INTO TMP_CAB_DV
        (
            COMPRONUMEDEVST,
            DEVOLUCIONID
        )
        VALUES
        (
            CAB.COMPRONUMEDEVST,
            v_devolucion_id
        );

    END LOOP;


    -------------------------------------------------------------------------
    -- 8. CREAR DEVOLUCIONPRODUCTO
    -------------------------------------------------------------------------
    INSERT INTO DEVOLUCIONPRODUCTO
    (
        DEVOLUCIONID,
        PRODUCTOSID,
        DEVOLUCIONPRODUCTOCANTIDAD,
        DEVOLUCIONPRODUCTOCANTIDADPR,
        DEVOLUCIONPRODUCTOESTADO
    )
    SELECT
        C.DEVOLUCIONID,
        P.PRODUCTOSID,
        P.CANTIDADPRODUCTO,
        0,
        'P'

    FROM TMP_PROD_DV P

    INNER JOIN TMP_CAB_DV C
        ON C.COMPRONUMEDEVST =
           P.COMPRONUMEDEVST;


    -------------------------------------------------------------------------
    -- OBTENER DEVOLUCIONPRODUCTOID GENERADO
    -------------------------------------------------------------------------
    MERGE INTO TMP_PROD_DV PDV
    USING
    (
        SELECT
            C.COMPRONUMEDEVST,
            DP.PRODUCTOSID,
            DP.DEVOLUCIONPRODUCTOID

        FROM TMP_CAB_DV C

        INNER JOIN DEVOLUCIONPRODUCTO DP
            ON DP.DEVOLUCIONID = C.DEVOLUCIONID

    ) X

    ON
    (
        X.COMPRONUMEDEVST = PDV.COMPRONUMEDEVST
    AND X.PRODUCTOSID     = PDV.PRODUCTOSID
    )

    WHEN MATCHED THEN
        UPDATE SET
            PDV.DEVOLUCIONPRODUCTOID =
                X.DEVOLUCIONPRODUCTOID;


    -------------------------------------------------------------------------
    -- 9. PROCESAR GRUPOS FINOS
    -------------------------------------------------------------------------
    FOR DET IN
    (
        SELECT
            G.PRODUC,
            G.DEPO,
            G.UBI,
            G.CANTIDADDEVUELTA,

            PDV.PRODUCTOSID,
            PDV.PRODUCTOSUNIDADMEDIDA,
            PDV.DEVOLUCIONPRODUCTOID

        FROM TMP_GRUPOS_DV G

        INNER JOIN TMP_PROD_DV PDV
            ON PDV.COMPRONUMEDEVST =
               G.COMPRONUMEDEVST

           AND PDV.PRODUC =
               G.PRODUC
    )
    LOOP

        DELETE FROM TMP_UNID_DV;

        v_deposito_id := NULL;
        v_disponibles := 0;


        ---------------------------------------------------------------------
        -- BUSCAR DEPOSITO DESTINO
        ---------------------------------------------------------------------
        BEGIN

            SELECT DEPOSITOSID
              INTO v_deposito_id
              FROM
              (
                  SELECT D.DEPOSITOSID
                  FROM DEPOSITOS D
                  WHERE D.DEPOSITOSCODIGO =
                        NULLIF(DET.DEPO, CHR(1))
              )
             WHERE ROWNUM = 1;

        EXCEPTION

            WHEN NO_DATA_FOUND THEN

                RAISE_APPLICATION_ERROR
                (
                    -20002,
                    'No se encontro DepositosId destino para devolucion'
                );

        END;


        ---------------------------------------------------------------------
        -- SOLO PRODUCTOS CUYA UNIDAD ES UN
        ---------------------------------------------------------------------
        IF UPPER(TRIM(DET.PRODUCTOSUNIDADMEDIDA)) = 'UN' THEN

            SELECT COUNT(*)
              INTO v_disponibles
              FROM EXISTENCIASDETALLE ED
             WHERE ED.PRODUCTOSID = DET.PRODUCTOSID
               AND ED.DEPOSITOSID = 48
               AND ED.EXISTENCIASDETALLEESTADO = 'E';


            IF NVL(v_disponibles, 0) <
               DET.CANTIDADDEVUELTA
            THEN

                RAISE_APPLICATION_ERROR
                (
                    -20003,
                    'No hay suficientes unidades egresadas para dejar la devolucion pendiente de confirmacion'
                );

            END IF;


            -----------------------------------------------------------------
            -- TOMAR LAS PRIMERAS N UNIDADES
            -----------------------------------------------------------------
            INSERT INTO TMP_UNID_DV
            (
                EXISTENCIASDETALLEID
            )
            SELECT EXISTENCIASDETALLEID
            FROM
            (
                SELECT
                    ED.EXISTENCIASDETALLEID

                FROM EXISTENCIASDETALLE ED

                WHERE ED.PRODUCTOSID =
                      DET.PRODUCTOSID

                  AND ED.DEPOSITOSID = 48

                  AND ED.EXISTENCIASDETALLEESTADO = 'E'

                ORDER BY
                    ED.EXISTENCIASDETALLEID
            )
            WHERE ROWNUM <=
                  DET.CANTIDADDEVUELTA;


            -----------------------------------------------------------------
            -- CREAR DEVOLUCIONUNIDAD
            -----------------------------------------------------------------
            INSERT INTO DEVOLUCIONUNIDAD
            (
                DEVOLUCIONPRODUCTOID,
                EXISTENCIASDETALLEID,
                DEVOLUCIONUNIDADESTADO,
                DEVOLUCIONUNIDADFCHALTA,
                DEVOLUCIONUNIDADOBSERVACION,
                ST_DEPOSITODEVOLUCIONID,
                ST_ORGANIGRAMADEVOLUCIONID,
                ST_FUENTEDEVOLUCIONID
            )
            SELECT
                DET.DEVOLUCIONPRODUCTOID,
                ED.EXISTENCIASDETALLEID,
                'P',
                SYSDATE,

                'Generado automaticamente desde DEVST',

                v_deposito_id,

                ED.ORGANIGRAMAID,

                ED.FUENTESABASTECIMIENTOID

            FROM EXISTENCIASDETALLE ED

            INNER JOIN TMP_UNID_DV U
                ON U.EXISTENCIASDETALLEID =
                   ED.EXISTENCIASDETALLEID;


            -----------------------------------------------------------------
            -- ACTUALIZAR EXISTENCIASDETALLE
            -----------------------------------------------------------------
            UPDATE EXISTENCIASDETALLE ED
               SET ED.DEPOSITOSID =
                   v_deposito_id,

                   ED.EXISTENCIASDETALLEESTADO =
                   'C'

             WHERE EXISTS
             (
                 SELECT 1
                 FROM TMP_UNID_DV U
                 WHERE U.EXISTENCIASDETALLEID =
                       ED.EXISTENCIASDETALLEID
             );

        END IF;

    END LOOP;


    -------------------------------------------------------------------------
    -- 10. ACTUALIZAR PRODUCTOSCANTIDADACTUAL
    -------------------------------------------------------------------------
    MERGE INTO PRODUCTOS P

    USING
    (
        SELECT
            P2.PRODUCTOSID,

            CASE

                -------------------------------------------------------------
                -- PRODUCTOS POR UNIDAD
                -------------------------------------------------------------
                WHEN UPPER(
                        TRIM(
                            UM.UNIDADESMEDIDACODIGO
                        )
                    ) = 'UN'

                THEN
                    NVL
                    (
                        (
                            SELECT
                                MAX
                                (
                                    TO_NUMBER(
                                        ED.EXISTENCIASDETALLECODIGO
                                    )
                                )

                            FROM EXISTENCIASDETALLE ED

                            WHERE ED.PRODUCTOSID =
                                P2.PRODUCTOSID

                            AND REGEXP_LIKE
                                (
                                    TRIM(
                                        ED.EXISTENCIASDETALLECODIGO
                                    ),
                                    '^[0-9]+$'
                                )
                        ),
                        0
                    )

                -------------------------------------------------------------
                -- PRODUCTOS POR CANTIDAD
                -------------------------------------------------------------
                ELSE
                    NVL
                    (
                        (
                            SELECT
                                SUM
                                (
                                    NVL(
                                        E.EXISTENCIASCANTIDAD,
                                        0
                                    )
                                )

                            FROM EXISTENCIAS E

                            WHERE E.EXISTENCIASPRODUCTOCODI =
                                P2.PRODUCTOSCODIGO
                        ),
                        0
                    )

            END AS NUEVACANTIDAD

        FROM PRODUCTOS P2

        LEFT JOIN UNIDADESMEDIDA UM
            ON UM.UNIDADESMEDIDAID =
            P2.UNIDADESMEDIDAID

        WHERE EXISTS
        (
            SELECT 1
            FROM TMP_PROD_DV PDV
            WHERE PDV.PRODUCTOSID =
                P2.PRODUCTOSID
        )

    ) X

    ON
    (
        X.PRODUCTOSID =
        P.PRODUCTOSID
    )

    WHEN MATCHED THEN
        UPDATE SET
            P.PRODUCTOSCANTIDADACTUAL =
            X.NUEVACANTIDAD;


    -------------------------------------------------------------------------
    -- 11. MARCAR LOS CAMBIOS COMO PROCESADOS
    -------------------------------------------------------------------------
    UPDATE INTEGRACIONEXISTCONTROL C

       SET C.IECDETALLEPROCESADO = 1,
           C.IECERRORDETALLEMENSAJE = NULL,
           C.IECFCHULTIMOPROCESO = SYSDATE

     WHERE EXISTS
     (
         SELECT 1
         FROM TMP_PEND_DV P
         WHERE P.CAMBIOID =
               C.IECCAMBIOID
     );


    COMMIT;


EXCEPTION

    WHEN OTHERS THEN

        v_error :=
            SUBSTR(
                SQLERRM,
                1,
                1000
            );

        ROLLBACK;


        ---------------------------------------------------------------------
        -- GUARDAR EL ERROR EN INTEGRACIONEXISTCONTROL
        ---------------------------------------------------------------------
        UPDATE INTEGRACIONEXISTCONTROL C

           SET C.IECERRORDETALLEMENSAJE =
               v_error,

               C.IECFCHULTIMOPROCESO =
               SYSDATE

         WHERE EXISTS
         (
             SELECT 1
             FROM TMP_PEND_DV P
             WHERE P.CAMBIOID =
                   C.IECCAMBIOID
         );


        COMMIT;

        RAISE;
END; 
/
CREATE PROCEDURE SP_PROCESAR_EXISTENCIAS_AMER
AS
    v_cantidad NUMBER;
    v_error    VARCHAR2(1000);

BEGIN

    -------------------------------------------------------------------------
    -- LIMPIAR TEMPORALES DE LA SESION
    -------------------------------------------------------------------------
    DELETE FROM TMP_ESTADO_EXIST;
    DELETE FROM TMP_CLAVES_EXIST;
    DELETE FROM TMP_INT_EXIST;
    DELETE FROM TMP_PEND_EXIST;

    COMMIT;


    -------------------------------------------------------------------------
    -- 1. PENDIENTES LOCALES
    --    Pendiente de Existencias O pendiente de Detalle
    -------------------------------------------------------------------------
    INSERT INTO TMP_PEND_EXIST
    (
        CAMBIOID
    )
    SELECT
        C.IECCAMBIOID
    FROM INTEGRACIONEXISTCONTROL C
    WHERE NVL(C.IECEXISTENCIASPROCESADAS, 0) = 0
       OR NVL(C.IECDETALLEPROCESADO, 0) = 0;


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_PEND_EXIST;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- 2. TRAER INTEGRACIONEXISTENCIAS DESDE SQL SERVER
    -------------------------------------------------------------------------
    INSERT INTO TMP_INT_EXIST
    (
        CAMBIOID,
        TIPOOPERACION,
        PRODUC,
        DEPO,
        UBI,
        CANTIREALANTERIOR,
        CANTIREALNUEVO,
        COMPROCODI,
        COMPRONUME,
        COMPROLINEA,
        COMPROFECHA
    )
    SELECT
        R."CambioId",
        RTRIM(R."TipoOperacion"),
        R."Produc",
        R."Depo",
        R."Ubi",
        R."CantiRealAnterior",
        R."CantiRealNuevo",
        RTRIM(R."ComproCodi"),
        R."ComproNume",
        R."ComproLinea",
        R."ComproFecha"

    FROM dbo.IntegracionExistencias@MSSQL R

    INNER JOIN TMP_PEND_EXIST P
        ON P.CAMBIOID = R."CambioId";


    IF SQL%ROWCOUNT = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    COMMIT;


    -------------------------------------------------------------------------
    -- 3. CLASIFICAR MOVIMIENTOS DE DETALLE
    -------------------------------------------------------------------------
    SELECT COUNT(*)
      INTO v_cantidad
      FROM INTEGRACIONEXISTCONTROL C
     WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0
       AND EXISTS
       (
           SELECT 1
           FROM TMP_PEND_EXIST P
           WHERE P.CAMBIOID = C.IECCAMBIOID
       );


    IF v_cantidad > 0 THEN

        UPDATE INTEGRACIONEXISTCONTROL C
           SET C.IECTIPOMOVIMIENTODETALLE = NULL
         WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0
           AND EXISTS
           (
               SELECT 1
               FROM TMP_PEND_EXIST P
               WHERE P.CAMBIOID = C.IECCAMBIOID
           );

        COMMIT;

        SP_CLASIF_MOV_DET_AMER;

    END IF;


    -------------------------------------------------------------------------
    -- 4. CLAVES AFECTADAS
    --    SOLO pendientes de EXISTENCIAS
    --    EXCLUIR DV
    -------------------------------------------------------------------------
    DELETE FROM TMP_CLAVES_EXIST;


    INSERT INTO TMP_CLAVES_EXIST
    (
        PRODUC,
        DEPO,
        UBI
    )
    SELECT DISTINCT
        R.PRODUC,
        NVL(R.DEPO, CHR(1)),
        NVL(R.UBI,  CHR(1))

    FROM TMP_INT_EXIST R

    INNER JOIN INTEGRACIONEXISTCONTROL C
        ON C.IECCAMBIOID = R.CAMBIOID

    WHERE NVL(C.IECEXISTENCIASPROCESADAS, 0) = 0
      AND NVL(C.IECTIPOMOVIMIENTODETALLE, ' ') <> 'DV';


    -------------------------------------------------------------------------
    -- 5. ESTADO ACTUAL REAL DESDE AMERICA
    -------------------------------------------------------------------------
    DELETE FROM TMP_ESTADO_EXIST;


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_CLAVES_EXIST;


    IF v_cantidad > 0 THEN

        INSERT INTO TMP_ESTADO_EXIST
        (
            PRODUC,
            DEPO,
            UBI,
            DESCRIP,
            CANTIDAD,
            DEPOSITODESCR,
            COSTOULTICOMPRA,
            FCHULTICOMPRA,
            CUENTA
        )
        SELECT
            DET."produc",

            NVL(
                DET."depo",
                CHR(1)
            ),

            NVL(
                DET."ubi",
                CHR(1)
            ),

            REPLACE(
                P."descrip_larga",
                ';',
                ' '
            ),

            DET."canti_real",
            D."descrip",
            P."costo_ulti_compra",
            P."fecha_ulti_compra",
            P."cuenta"

        FROM dbo.produc_deta@MSSQL DET

        INNER JOIN dbo.productos@MSSQL P
            ON P."produc" = DET."produc"

        INNER JOIN dbo.depositos@MSSQL D
            ON D."depo" = DET."depo"

        INNER JOIN TMP_CLAVES_EXIST K
            ON K.PRODUC = DET."produc"

           AND K.DEPO =
               NVL(
                   DET."depo",
                   CHR(1)
               )

           AND K.UBI =
               NVL(
                   DET."ubi",
                   CHR(1)
               );

    END IF;


    -------------------------------------------------------------------------
    -- 6 + 7.
    -- ACTUALIZAR EXISTENCIAS EXISTENTES / INSERTAR NUEVAS
    -------------------------------------------------------------------------
    MERGE INTO EXISTENCIAS E

    USING TMP_ESTADO_EXIST A

    ON
    (
           E.EXISTENCIASPRODUCTOCODI = A.PRODUC

       AND NVL(
               E.EXISTENCIASDEPOSITOCODI,
               CHR(1)
           ) = A.DEPO

       AND NVL(
               E.EXISTENCIASUBICACIONCODI,
               CHR(1)
           ) = A.UBI
    )

    WHEN MATCHED THEN
        UPDATE SET

            E.EXISTENCIASPRODUCTODESCR =
                A.DESCRIP,

            E.EXISTENCIASCANTIDAD =
                A.CANTIDAD,

            E.EXISTENCIASDEPOSITODESCR =
                A.DEPOSITODESCR,

            E.EXISTENCIASCOSTOULTICOMPRA =
                A.COSTOULTICOMPRA,

            E.EXISTENCIASFCHULTICOMPRA =
                A.FCHULTICOMPRA,

            E.EXISTENCIASCUENTACODI =
                A.CUENTA


    WHEN NOT MATCHED THEN
        INSERT
        (
            EXISTENCIASPRODUCTOCODI,
            EXISTENCIASPRODUCTODESCR,
            EXISTENCIASCANTIDAD,
            EXISTENCIASDEPOSITOCODI,
            EXISTENCIASDEPOSITODESCR,
            EXISTENCIASUBICACIONCODI,
            EXISTENCIASCOSTOULTICOMPRA,
            EXISTENCIASFCHULTICOMPRA,
            EXISTENCIASCUENTACODI
        )
        VALUES
        (
            A.PRODUC,
            A.DESCRIP,
            A.CANTIDAD,
            NULLIF(A.DEPO, CHR(1)),
            A.DEPOSITODESCR,
            NULLIF(A.UBI, CHR(1)),
            A.COSTOULTICOMPRA,
            A.FCHULTICOMPRA,
            A.CUENTA
        );


    -------------------------------------------------------------------------
    -- 8. SI YA NO EXISTE EN PRODUC_DETA ? CANTIDAD = 0
    -------------------------------------------------------------------------
    UPDATE EXISTENCIAS E

       SET E.EXISTENCIASCANTIDAD = 0

     WHERE EXISTS
     (
         SELECT 1

         FROM TMP_CLAVES_EXIST K

         WHERE K.PRODUC =
               E.EXISTENCIASPRODUCTOCODI

           AND K.DEPO =
               NVL(
                   E.EXISTENCIASDEPOSITOCODI,
                   CHR(1)
               )

           AND K.UBI =
               NVL(
                   E.EXISTENCIASUBICACIONCODI,
                   CHR(1)
               )

           AND NOT EXISTS
           (
               SELECT 1

               FROM TMP_ESTADO_EXIST A

               WHERE A.PRODUC =
                     K.PRODUC

                 AND A.DEPO =
                     K.DEPO

                 AND A.UBI =
                     K.UBI
           )
     );


    -------------------------------------------------------------------------
    -- 9. MARCAR PROCESADO EXISTENCIAS
    --    EXCEPTO DV
    -------------------------------------------------------------------------
    UPDATE INTEGRACIONEXISTCONTROL C

       SET C.IECEXISTENCIASPROCESADAS = 1,
           C.IECERROREXISTENCIASMENSAJE = NULL,
           C.IECFCHULTIMOPROCESO = SYSDATE

     WHERE NVL(C.IECEXISTENCIASPROCESADAS, 0) = 0

       AND NVL(
               C.IECTIPOMOVIMIENTODETALLE,
               ' '
           ) <> 'DV'

       AND EXISTS
       (
           SELECT 1

           FROM TMP_PEND_EXIST P

           WHERE P.CAMBIOID =
                 C.IECCAMBIOID
       );


    COMMIT;


    -------------------------------------------------------------------------
    -- 10. PROCESAR DEVOLUCIONES
    -------------------------------------------------------------------------
    SELECT COUNT(*)
      INTO v_cantidad

      FROM INTEGRACIONEXISTCONTROL C

     WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

       AND C.IECTIPOMOVIMIENTODETALLE = 'DV'

       AND EXISTS
       (
           SELECT 1
           FROM TMP_PEND_EXIST P
           WHERE P.CAMBIOID = C.IECCAMBIOID
       );


    IF v_cantidad > 0 THEN

        BEGIN

            SP_PROCESAR_DEVOLUCIONES_AMER;


            UPDATE INTEGRACIONEXISTCONTROL C

               SET C.IECEXISTENCIASPROCESADAS = 1,
                   C.IECERROREXISTENCIASMENSAJE = NULL,
                   C.IECFCHULTIMOPROCESO = SYSDATE

             WHERE NVL(C.IECEXISTENCIASPROCESADAS, 0) = 0

               AND C.IECTIPOMOVIMIENTODETALLE = 'DV'

               AND EXISTS
               (
                   SELECT 1

                   FROM TMP_PEND_EXIST P

                   WHERE P.CAMBIOID =
                         C.IECCAMBIOID
               );


            COMMIT;


        EXCEPTION

            WHEN OTHERS THEN

                v_error :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_error,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND C.IECTIPOMOVIMIENTODETALLE = 'DV'

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_PEND_EXIST P

                       WHERE P.CAMBIOID =
                             C.IECCAMBIOID
                   );


                COMMIT;

                RAISE;

        END;

    END IF;


    -------------------------------------------------------------------------
    -- 11. PROCESAR TRANSFERENCIAS
    --
    -- Nombre provisional hasta que convirtamos ese procedure.
    -------------------------------------------------------------------------
    SELECT COUNT(*)
      INTO v_cantidad

      FROM INTEGRACIONEXISTCONTROL C

     WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

       AND C.IECTIPOMOVIMIENTODETALLE = 'T'

       AND EXISTS
       (
           SELECT 1
           FROM TMP_PEND_EXIST P
           WHERE P.CAMBIOID = C.IECCAMBIOID
       );


    IF v_cantidad > 0 THEN

        BEGIN

            EXECUTE IMMEDIATE
                'BEGIN SP_PROC_TRANSF_EXIST_DET_AMER; END;';


        EXCEPTION

            WHEN OTHERS THEN

                v_error :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_error,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND C.IECTIPOMOVIMIENTODETALLE = 'T'

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_PEND_EXIST P

                       WHERE P.CAMBIOID =
                             C.IECCAMBIOID
                   );


                COMMIT;

                RAISE;

        END;

    END IF;


    -------------------------------------------------------------------------
    -- 12. PROCESAR EGRESOS
    -------------------------------------------------------------------------
    SELECT COUNT(*)
      INTO v_cantidad

      FROM INTEGRACIONEXISTCONTROL C

     WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

       AND C.IECTIPOMOVIMIENTODETALLE = 'E'

       AND EXISTS
       (
           SELECT 1
           FROM TMP_PEND_EXIST P
           WHERE P.CAMBIOID = C.IECCAMBIOID
       );


    IF v_cantidad > 0 THEN

        BEGIN

            SP_PROC_EGR_EXIST_DET_AMER;


        EXCEPTION

            WHEN OTHERS THEN

                v_error :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_error,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND C.IECTIPOMOVIMIENTODETALLE = 'E'

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_PEND_EXIST P

                       WHERE P.CAMBIOID =
                             C.IECCAMBIOID
                   );


                COMMIT;

                RAISE;

        END;

    END IF;


    -------------------------------------------------------------------------
    -- 13. PROCESAR INGRESOS
    --
    -- Nombre provisional hasta que convirtamos ese procedure.
    -------------------------------------------------------------------------
    SELECT COUNT(*)
      INTO v_cantidad

      FROM INTEGRACIONEXISTCONTROL C

     WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

       AND C.IECTIPOMOVIMIENTODETALLE = 'I'

       AND EXISTS
       (
           SELECT 1
           FROM TMP_PEND_EXIST P
           WHERE P.CAMBIOID = C.IECCAMBIOID
       );


    IF v_cantidad > 0 THEN

        BEGIN

            EXECUTE IMMEDIATE
                'BEGIN SP_PROC_ING_EXIST_DET_AMER; END;';


        EXCEPTION

            WHEN OTHERS THEN

                v_error :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_error,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND C.IECTIPOMOVIMIENTODETALLE = 'I'

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_PEND_EXIST P

                       WHERE P.CAMBIOID =
                             C.IECCAMBIOID
                   );


                COMMIT;

                RAISE;

        END;

    END IF;


EXCEPTION

    -------------------------------------------------------------------------
    -- ERROR GENERAL
    -------------------------------------------------------------------------
    WHEN OTHERS THEN

        v_error :=
            SUBSTR(
                SQLERRM,
                1,
                1000
            );


        ROLLBACK;


        UPDATE INTEGRACIONEXISTCONTROL C

           SET C.IECERROREXISTENCIASMENSAJE =
               v_error,

               C.IECFCHULTIMOPROCESO =
               SYSDATE

         WHERE NVL(C.IECEXISTENCIASPROCESADAS, 0) = 0

           AND EXISTS
           (
               SELECT 1

               FROM TMP_PEND_EXIST P

               WHERE P.CAMBIOID =
                     C.IECCAMBIOID
           );


        COMMIT;

        RAISE;

END; 
/
CREATE PROCEDURE SP_PROC_EGR_EXIST_DET_AMER
AS
    v_productos_id        NUMBER;
    v_unidad_medida       VARCHAR2(80);
    v_deposito_origen_id  NUMBER;
    v_deposito_sin_id     NUMBER := 48;
    v_disponible          NUMBER;
    v_filas               NUMBER;
    v_msg                 VARCHAR2(1000);

    e_movimiento_error EXCEPTION;

BEGIN

    -------------------------------------------------------------------------
    -- LIMPIAR TEMPORALES DE EJECUCIONES ANTERIORES DE LA SESION
    -------------------------------------------------------------------------
    DELETE FROM TMP_DET_EGR;
    DELETE FROM TMP_MOV_EGR;
    DELETE FROM TMP_INT_EGR;
    DELETE FROM TMP_PEND_EGR;

    COMMIT;


    -------------------------------------------------------------------------
    -- 1. PENDIENTES DE DETALLE CLASIFICADOS COMO EGRESO
    -------------------------------------------------------------------------
    INSERT INTO TMP_PEND_EGR
    (
        CAMBIOID
    )
    SELECT
        C.IECCAMBIOID
    FROM INTEGRACIONEXISTCONTROL C
    WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0
      AND C.IECTIPOMOVIMIENTODETALLE = 'E';


    IF SQL%ROWCOUNT = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- 2. TRAER INTEGRACIONEXISTENCIAS DESDE SQL SERVER
    -------------------------------------------------------------------------
    INSERT INTO TMP_INT_EGR
    (
        CAMBIOID,
        TIPOOPERACION,
        PRODUC,
        DEPO,
        UBI,
        COMPROCodi,
        CANTIREALANTERIOR,
        CANTIREALNUEVO
    )
    SELECT
        R."CambioId",
        RTRIM(R."TipoOperacion"),
        R."Produc",
        R."Depo",
        R."Ubi",
        RTRIM(R."ComproCodi"),
        R."CantiRealAnterior",
        R."CantiRealNuevo"

    FROM dbo.IntegracionExistencias@MSSQL R

    INNER JOIN TMP_PEND_EGR P
        ON P.CAMBIOID = R."CambioId";


    -------------------------------------------------------------------------
    -- 3. CALCULAR MOVIMIENTOS DE EGRESO
    --
    -- DELETE con CantiRealAnterior = 0 se ignora.
    -------------------------------------------------------------------------
    INSERT INTO TMP_MOV_EGR
    (
        CAMBIOID,
        PRODUC,
        DEPO,
        UBI,
        CANTIDADEGRESO
    )
    SELECT
        R.CAMBIOID,
        R.PRODUC,
        R.DEPO,
        R.UBI,

        TRUNC
        (
            CASE

                WHEN RTRIM(R.TIPOOPERACION) = 'D'
                THEN
                    NVL(R.CANTIREALANTERIOR, 0)

                WHEN RTRIM(R.TIPOOPERACION) = 'U'
                 AND NVL(R.CANTIREALNUEVO, 0)
                     < NVL(R.CANTIREALANTERIOR, 0)
                THEN
                    NVL(R.CANTIREALANTERIOR, 0)
                    -
                    NVL(R.CANTIREALNUEVO, 0)

                ELSE 0

            END
        )

    FROM TMP_INT_EGR R

    WHERE
    (
        RTRIM(R.TIPOOPERACION) = 'U'
        AND NVL(R.CANTIREALNUEVO, 0)
            < NVL(R.CANTIREALANTERIOR, 0)
    )
    OR
    (
        RTRIM(R.TIPOOPERACION) = 'D'
        AND NVL(R.CANTIREALANTERIOR, 0) > 0
    );


    IF SQL%ROWCOUNT = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- Confirmamos staging.
    -- Las GTT usan PRESERVE ROWS, por lo que permanecen disponibles.
    -------------------------------------------------------------------------
    COMMIT;


    -------------------------------------------------------------------------
    -- 4. RECORRER MOVIMIENTOS
    -------------------------------------------------------------------------
    FOR MOV IN
    (
        SELECT
            CAMBIOID,
            PRODUC,
            DEPO,
            UBI,
            CANTIDADEGRESO

        FROM TMP_MOV_EGR

        ORDER BY CAMBIOID
    )
    LOOP

        BEGIN

            SAVEPOINT SP_MOVIMIENTO;

            v_productos_id       := NULL;
            v_unidad_medida      := NULL;
            v_deposito_origen_id := NULL;
            v_disponible         := 0;
            v_filas              := 0;
            v_msg                := NULL;

            DELETE FROM TMP_DET_EGR;


            -----------------------------------------------------------------
            -- VALIDAR CANTIDAD
            -----------------------------------------------------------------
            IF NVL(MOV.CANTIDADEGRESO, 0) <= 0 THEN

                v_msg := 'CantidadEgreso calculada <= 0';

                RAISE e_movimiento_error;

            END IF;


            -----------------------------------------------------------------
            -- BUSCAR PRODUCTO Y UNIDAD DE MEDIDA
            -----------------------------------------------------------------
            BEGIN

                SELECT
                    X.PRODUCTOSID,
                    X.UNIDADMEDIDA

                INTO
                    v_productos_id,
                    v_unidad_medida

                FROM
                (
                    SELECT
                        P.PRODUCTOSID,
                        UM.UNIDADESMEDIDACODIGO AS UNIDADMEDIDA

                    FROM PRODUCTOS P

                    LEFT JOIN UNIDADESMEDIDA UM
                        ON UM.UNIDADESMEDIDAID =
                           P.UNIDADESMEDIDAID

                    WHERE P.PRODUCTOSCODIGO =
                          MOV.PRODUC
                ) X

                WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro ProductosId local';

                    RAISE e_movimiento_error;

            END;


            -----------------------------------------------------------------
            -- BUSCAR DEPOSITO DE ORIGEN
            -----------------------------------------------------------------
            BEGIN

                SELECT X.DEPOSITOSID

                INTO v_deposito_origen_id

                FROM
                (
                    SELECT
                        D.DEPOSITOSID

                    FROM DEPOSITOS D

                    WHERE D.DEPOSITOSCODIGO =
                          MOV.DEPO
                ) X

                WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro DepositosId origen local';

                    RAISE e_movimiento_error;

            END;


            -----------------------------------------------------------------
            -- PRODUCTOS POR UNIDAD
            -----------------------------------------------------------------
            IF UPPER(TRIM(v_unidad_medida)) = 'UN' THEN


                -------------------------------------------------------------
                -- CANTIDAD DISPONIBLE EN EL DEPOSITO
                -------------------------------------------------------------
                SELECT COUNT(*)

                INTO v_disponible

                FROM EXISTENCIASDETALLE ED

                WHERE ED.PRODUCTOSID =
                      v_productos_id

                  AND ED.DEPOSITOSID =
                      v_deposito_origen_id

                  AND ED.EXISTENCIASDETALLEESTADO =
                      'D'

                  AND ED.ORGANIGRAMAID =
                      51;


                IF NVL(v_disponible, 0) <
                   MOV.CANTIDADEGRESO
                THEN

                    v_msg :=
                        'Egreso mayor a detalles disponibles';

                    RAISE e_movimiento_error;

                END IF;


                -------------------------------------------------------------
                -- SELECCIONAR LAS PRIMERAS N UNIDADES
                -------------------------------------------------------------
                INSERT INTO TMP_DET_EGR
                (
                    EXISTENCIASDETALLEID
                )
                SELECT
                    EXISTENCIASDETALLEID

                FROM
                (
                    SELECT
                        ED.EXISTENCIASDETALLEID

                    FROM EXISTENCIASDETALLE ED

                    WHERE ED.PRODUCTOSID =
                          v_productos_id

                      AND ED.DEPOSITOSID =
                          v_deposito_origen_id

                      AND ED.EXISTENCIASDETALLEESTADO =
                          'D'

                      AND ED.ORGANIGRAMAID =
                          51

                    ORDER BY
                        ED.EXISTENCIASDETALLEID
                )

                WHERE ROWNUM <=
                      MOV.CANTIDADEGRESO;


                -------------------------------------------------------------
                -- MARCAR LAS UNIDADES
                -------------------------------------------------------------
                UPDATE EXISTENCIASDETALLE ED

                   SET ED.EXISTENCIASDETALLEESTADO = 'P',
                       ED.ORGANIGRAMAID = 51

                 WHERE EXISTS
                 (
                     SELECT 1

                     FROM TMP_DET_EGR T

                     WHERE T.EXISTENCIASDETALLEID =
                           ED.EXISTENCIASDETALLEID
                 );


                v_filas := SQL%ROWCOUNT;


                IF v_filas <> MOV.CANTIDADEGRESO THEN

                    v_msg :=
                        'Se esperaban mover '
                        || TO_CHAR(MOV.CANTIDADEGRESO)
                        || ' filas y se movieron '
                        || TO_CHAR(v_filas);

                    RAISE e_movimiento_error;

                END IF;


            -----------------------------------------------------------------
            -- PRODUCTOS QUE NO SON UN
            -----------------------------------------------------------------
            ELSE

                -------------------------------------------------------------
                -- TOMAR UNA FILA REPRESENTATIVA
                -------------------------------------------------------------
                INSERT INTO TMP_DET_EGR
                (
                    EXISTENCIASDETALLEID
                )
                SELECT
                    EXISTENCIASDETALLEID

                FROM
                (
                    SELECT
                        ED.EXISTENCIASDETALLEID

                    FROM EXISTENCIASDETALLE ED

                    WHERE ED.PRODUCTOSID =
                          v_productos_id

                      AND ED.DEPOSITOSID =
                          v_deposito_origen_id

                      AND ED.EXISTENCIASDETALLEESTADO =
                          'D'

                      AND ED.ORGANIGRAMAID =
                          51

                    ORDER BY
                        ED.EXISTENCIASDETALLEID
                )

                WHERE ROWNUM = 1;


                -------------------------------------------------------------
                -- ACTUALIZAR FILA REPRESENTATIVA
                -------------------------------------------------------------
                UPDATE EXISTENCIASDETALLE ED

                   SET ED.EXISTENCIASDETALLEESTADO = 'P',
                       ED.ORGANIGRAMAID = 51

                 WHERE EXISTS
                 (
                     SELECT 1

                     FROM TMP_DET_EGR T

                     WHERE T.EXISTENCIASDETALLEID =
                           ED.EXISTENCIASDETALLEID
                 );


                v_filas := SQL%ROWCOUNT;


                IF v_filas <> 1 THEN

                    v_msg :=
                        'No se encontro fila representativa no-UN';

                    RAISE e_movimiento_error;

                END IF;

            END IF;


            -----------------------------------------------------------------
            -- 5. HISTORICO DE DEPOSITOS
            -----------------------------------------------------------------
            INSERT INTO DEPOSITOSHISTORICO
            (
                EXISTENCIASDETALLEID,
                ST_DEPOSITOANTERIORID,
                ST_DEPOSITONUEVOID,
                DEPOSITOSHISTORICOFCHALTA
            )
            SELECT
                T.EXISTENCIASDETALLEID,
                v_deposito_origen_id,
                v_deposito_sin_id,
                SYSDATE

            FROM TMP_DET_EGR T;


            -----------------------------------------------------------------
            -- 6. MARCAR PROCESADO:
            --
            -- Movimiento real + DELETE residual de la misma combinación
            -- producto / depósito / ubicación.
            -----------------------------------------------------------------
            UPDATE INTEGRACIONEXISTCONTROL C

               SET C.IECDETALLEPROCESADO = 1,
                   C.IECERRORDETALLEMENSAJE = NULL,
                   C.IECFCHULTIMOPROCESO = SYSDATE

             WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

               AND EXISTS
               (
                   SELECT 1

                   FROM TMP_INT_EGR R

                   WHERE R.CAMBIOID =
                         C.IECCAMBIOID

                     AND R.PRODUC =
                         MOV.PRODUC

                     AND NVL(R.DEPO, CHR(1)) =
                         NVL(MOV.DEPO, CHR(1))

                     AND NVL(R.UBI, CHR(1)) =
                         NVL(MOV.UBI, CHR(1))

                     AND
                     (
                         -----------------------------------------------------
                         -- UPDATE QUE REDUCE CANTIDAD
                         -----------------------------------------------------
                         (
                             RTRIM(R.TIPOOPERACION) = 'U'

                             AND NVL(R.CANTIREALNUEVO, 0)
                                 <
                                 NVL(R.CANTIREALANTERIOR, 0)
                         )

                         OR

                         -----------------------------------------------------
                         -- DELETE RESIDUAL
                         -----------------------------------------------------
                         (
                             RTRIM(R.TIPOOPERACION) = 'D'

                             AND NVL(R.CANTIREALANTERIOR, 0)
                                 = 0
                         )

                         OR

                         -----------------------------------------------------
                         -- DELETE REAL
                         -----------------------------------------------------
                         (
                             RTRIM(R.TIPOOPERACION) = 'D'

                             AND NVL(R.CANTIREALANTERIOR, 0)
                                 > 0
                         )
                     )
               );


            -----------------------------------------------------------------
            -- MOVIMIENTO CORRECTO
            -----------------------------------------------------------------
            COMMIT;


        ---------------------------------------------------------------------
        -- ERROR CONTROLADO DE ESTE MOVIMIENTO
        ---------------------------------------------------------------------
        EXCEPTION

            WHEN e_movimiento_error THEN

                ROLLBACK TO SP_MOVIMIENTO;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       SUBSTR(v_msg, 1, 1000),

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE C.IECCAMBIOID =
                       MOV.CAMBIOID;


                COMMIT;


            -----------------------------------------------------------------
            -- ERROR INESPERADO DE ESTE MOVIMIENTO
            -----------------------------------------------------------------
            WHEN OTHERS THEN

                v_msg :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK TO SP_MOVIMIENTO;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_msg,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE C.IECCAMBIOID =
                       MOV.CAMBIOID;


                COMMIT;

        END;

    END LOOP;


EXCEPTION

    WHEN OTHERS THEN

        ROLLBACK;
        RAISE;

END; 
/
CREATE PROCEDURE SP_PROC_ING_EXIST_DET_AMER
AS
    v_productos_id      NUMBER;
    v_unidad_medida     VARCHAR2(80);
    v_depositos_id      NUMBER;

    v_cantidad_actual   NUMBER(18,4);
    v_cantidad_detalle  NUMBER;
    v_faltan            NUMBER;

    v_ultimo_codigo     NUMBER;
    v_nuevo_codigo      VARCHAR2(20);
    v_i                 NUMBER;

    v_cantidad          NUMBER;
    v_msg               VARCHAR2(1000);

    e_grupo_error EXCEPTION;

BEGIN

    -------------------------------------------------------------------------
    -- LIMPIAR TEMPORALES DE LA SESION
    -------------------------------------------------------------------------
    DELETE FROM TMP_GRUPOS_ING;
    DELETE FROM TMP_INT_ING;
    DELETE FROM TMP_PEND_ING;

    COMMIT;


    -------------------------------------------------------------------------
    -- 1. PENDIENTES DE DETALLE CLASIFICADOS COMO INGRESO
    -------------------------------------------------------------------------
    INSERT INTO TMP_PEND_ING
    (
        CAMBIOID
    )
    SELECT
        C.IECCAMBIOID
    FROM INTEGRACIONEXISTCONTROL C
    WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0
      AND C.IECTIPOMOVIMIENTODETALLE = 'I';


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_PEND_ING;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- 2. TRAER INTEGRACIONEXISTENCIAS DESDE SQL SERVER
    -------------------------------------------------------------------------
    INSERT INTO TMP_INT_ING
    (
        CAMBIOID,
        TIPOOPERACION,
        PRODUC,
        DEPO,
        UBI,
        COMPROCODI,
        CANTIREALNUEVO,
        CANTIREALANTERIOR
    )
    SELECT
        R."CambioId",
        RTRIM(R."TipoOperacion"),
        R."Produc",
        R."Depo",
        R."Ubi",
        RTRIM(R."ComproCodi"),
        R."CantiRealNuevo",
        R."CantiRealAnterior"

    FROM dbo.IntegracionExistencias@MSSQL R

    INNER JOIN TMP_PEND_ING P
        ON P.CAMBIOID = R."CambioId";


    -------------------------------------------------------------------------
    -- 3. ARMAR GRUPOS DE INGRESOS REALES
    -------------------------------------------------------------------------
    INSERT INTO TMP_GRUPOS_ING
    (
        PRODUC,
        DEPO,
        UBI
    )
    SELECT
        IE.PRODUC,
        NVL(IE.DEPO, CHR(1)),
        NVL(IE.UBI,  CHR(1))

    FROM TMP_INT_ING IE

    GROUP BY
        IE.PRODUC,
        NVL(IE.DEPO, CHR(1)),
        NVL(IE.UBI,  CHR(1))

    HAVING

        ---------------------------------------------------------------------
        -- DEBE EXISTIR UN COMPROBANTE DE INGRESO
        ---------------------------------------------------------------------
        SUM
        (
            CASE
                WHEN RTRIM(IE.COMPROCODI) IN
                (
                    'ISSI',
                    'INGEM',
                    'INGSI',
                    'ISCOC',
                    'ISFCP',
                    'INNGR',
                    'IREMA'
                )
                THEN 1
                ELSE 0
            END
        ) > 0

        AND

        ---------------------------------------------------------------------
        -- DEBE HABER UNA ALTA REAL
        ---------------------------------------------------------------------
        SUM
        (
            CASE

                WHEN RTRIM(IE.TIPOOPERACION) = 'I'
                THEN 1

                WHEN RTRIM(IE.TIPOOPERACION) = 'U'
                 AND NVL(IE.CANTIREALNUEVO, 0)
                     > NVL(IE.CANTIREALANTERIOR, 0)
                THEN 1

                ELSE 0

            END
        ) > 0;


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_GRUPOS_ING;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- CONFIRMAR STAGING
    -------------------------------------------------------------------------
    COMMIT;


    -------------------------------------------------------------------------
    -- 4. PROCESAR CADA PRODUCTO + DEPOSITO + UBICACION
    -------------------------------------------------------------------------
    FOR GRUPO IN
    (
        SELECT
            PRODUC,
            DEPO,
            UBI

        FROM TMP_GRUPOS_ING

        ORDER BY
            PRODUC,
            DEPO,
            UBI
    )
    LOOP

        BEGIN

            SAVEPOINT SP_GRUPO_ING;


            -----------------------------------------------------------------
            -- REINICIAR VARIABLES
            -----------------------------------------------------------------
            v_productos_id     := NULL;
            v_unidad_medida    := NULL;
            v_depositos_id     := NULL;
            v_cantidad_actual  := NULL;
            v_cantidad_detalle := 0;
            v_faltan           := 0;
            v_ultimo_codigo    := 0;
            v_nuevo_codigo     := NULL;
            v_i                := 0;
            v_msg              := NULL;


            -----------------------------------------------------------------
            -- 5. BUSCAR PRODUCTO LOCAL + UNIDAD DE MEDIDA
            -----------------------------------------------------------------
            BEGIN

                SELECT
                    X.PRODUCTOSID,
                    X.UNIDADMEDIDA

                INTO
                    v_productos_id,
                    v_unidad_medida

                FROM
                (
                    SELECT
                        P.PRODUCTOSID,
                        UM.UNIDADESMEDIDACODIGO AS UNIDADMEDIDA

                    FROM PRODUCTOS P

                    LEFT JOIN UNIDADESMEDIDA UM
                        ON UM.UNIDADESMEDIDAID =
                           P.UNIDADESMEDIDAID

                    WHERE P.PRODUCTOSCODIGO =
                          GRUPO.PRODUC
                ) X

                WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro ProductosId local';

                    RAISE e_grupo_error;

            END;


            -----------------------------------------------------------------
            -- 6. BUSCAR DEPOSITO LOCAL
            -----------------------------------------------------------------
            BEGIN

                SELECT X.DEPOSITOSID

                  INTO v_depositos_id

                  FROM
                  (
                      SELECT
                          D.DEPOSITOSID

                      FROM DEPOSITOS D

                      WHERE D.DEPOSITOSCODIGO =
                            NULLIF(
                                GRUPO.DEPO,
                                CHR(1)
                            )
                  ) X

                 WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro DepositosId local';

                    RAISE e_grupo_error;

            END;


            -----------------------------------------------------------------
            -- 7. OBTENER CANTIDAD ACTUAL REAL DESDE PRODUC_DETA
            -----------------------------------------------------------------
            BEGIN

                SELECT X.CANTIDADACTUAL

                  INTO v_cantidad_actual

                  FROM
                  (
                      SELECT
                          DET."canti_real" AS CANTIDADACTUAL

                      FROM dbo.produc_deta@MSSQL DET

                      WHERE DET."produc" =
                            GRUPO.PRODUC

                        AND NVL(
                                DET."depo",
                                CHR(1)
                            ) =
                            GRUPO.DEPO

                        AND NVL(
                                DET."ubi",
                                CHR(1)
                            ) =
                            GRUPO.UBI
                  ) X

                 WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No existe la combinacion en produc_deta';

                    RAISE e_grupo_error;

            END;


            -----------------------------------------------------------------
            -- 8. PRODUCTOS POR UNIDAD
            -----------------------------------------------------------------
            IF UPPER(TRIM(v_unidad_medida)) = 'UN' THEN


                -------------------------------------------------------------
                -- CANTIDAD DE DETALLES EXISTENTES
                -------------------------------------------------------------
                SELECT COUNT(*)

                  INTO v_cantidad_detalle

                  FROM EXISTENCIASDETALLE ED

                 WHERE ED.PRODUCTOSID =
                       v_productos_id

                   AND ED.DEPOSITOSID =
                       v_depositos_id

                   AND ED.EXISTENCIASDETALLEESTADO =
                       'D';


                v_cantidad_detalle :=
                    NVL(v_cantidad_detalle, 0);


                -------------------------------------------------------------
                -- CANTIDAD DE UNIDADES QUE FALTAN
                -------------------------------------------------------------
                v_faltan :=
                    TRUNC(v_cantidad_actual)
                    -
                    v_cantidad_detalle;


                IF v_faltan < 0 THEN

                    v_msg :=
                        'CantidadActual menor a cantidad de detalle existente';

                    RAISE e_grupo_error;

                END IF;


                -------------------------------------------------------------
                -- BUSCAR ULTIMO CODIGO NUMERICO DEL PRODUCTO
                -------------------------------------------------------------
                SELECT
                    NVL(
                        MAX(
                            TO_NUMBER(
                                ED.EXISTENCIASDETALLECODIGO
                            )
                        ),
                        0
                    )

                  INTO v_ultimo_codigo

                  FROM EXISTENCIASDETALLE ED

                 WHERE ED.PRODUCTOSID =
                       v_productos_id

                   AND REGEXP_LIKE
                       (
                           TRIM(
                               ED.EXISTENCIASDETALLECODIGO
                           ),
                           '^[0-9]+$'
                       );


                -------------------------------------------------------------
                -- CREAR LAS UNIDADES FALTANTES
                -------------------------------------------------------------
                IF v_faltan > 0 THEN

                    v_i := 1;


                    WHILE v_i <= v_faltan LOOP

                        v_ultimo_codigo :=
                            v_ultimo_codigo + 1;


                        v_nuevo_codigo :=
                            LPAD(
                                TO_CHAR(v_ultimo_codigo),
                                5,
                                '0'
                            );


                        INSERT INTO EXISTENCIASDETALLE
                        (
                            EXISTENCIASDETALLECODIGO,
                            PRODUCTOSID,
                            DEPOSITOSID,
                            ORGANIGRAMAID,
                            EXISTENCIASDETALLEORIGEN,
                            EXISTENCIASDETALLEESTADO
                        )
                        VALUES
                        (
                            v_nuevo_codigo,
                            v_productos_id,
                            v_depositos_id,
                            51,
                            'I',
                            'D'
                        );


                        v_i := v_i + 1;

                    END LOOP;

                END IF;


                -------------------------------------------------------------
                -- PARA UN:
                -- PRODUCTOSCANTIDADACTUAL = ULTIMO CODIGO UTILIZADO
                -------------------------------------------------------------
                UPDATE PRODUCTOS P

                   SET P.PRODUCTOSCANTIDADACTUAL =
                       v_ultimo_codigo

                 WHERE P.PRODUCTOSID =
                       v_productos_id;


            -----------------------------------------------------------------
            -- 9. PRODUCTOS NO UNITARIOS
            -----------------------------------------------------------------
            ELSE


                -------------------------------------------------------------
                -- CREAR UNA FILA REPRESENTATIVA SI NO EXISTE
                -------------------------------------------------------------
                SELECT COUNT(*)

                  INTO v_cantidad

                  FROM EXISTENCIASDETALLE ED

                 WHERE ED.PRODUCTOSID =
                       v_productos_id

                   AND ED.DEPOSITOSID =
                       v_depositos_id;


                IF v_cantidad = 0 THEN


                    ---------------------------------------------------------
                    -- BUSCAR ULTIMO CODIGO NUMERICO DEL PRODUCTO
                    ---------------------------------------------------------
                    SELECT
                        NVL(
                            MAX(
                                TO_NUMBER(
                                    ED.EXISTENCIASDETALLECODIGO
                                )
                            ),
                            0
                        )

                      INTO v_ultimo_codigo

                      FROM EXISTENCIASDETALLE ED

                     WHERE ED.PRODUCTOSID =
                           v_productos_id

                       AND REGEXP_LIKE
                           (
                               TRIM(
                                   ED.EXISTENCIASDETALLECODIGO
                               ),
                               '^[0-9]+$'
                           );


                    v_ultimo_codigo :=
                        v_ultimo_codigo + 1;


                    v_nuevo_codigo :=
                        LPAD(
                            TO_CHAR(v_ultimo_codigo),
                            5,
                            '0'
                        );


                    INSERT INTO EXISTENCIASDETALLE
                    (
                        EXISTENCIASDETALLECODIGO,
                        PRODUCTOSID,
                        DEPOSITOSID,
                        ORGANIGRAMAID,
                        EXISTENCIASDETALLEORIGEN,
                        EXISTENCIASDETALLEESTADO
                    )
                    VALUES
                    (
                        v_nuevo_codigo,
                        v_productos_id,
                        v_depositos_id,
                        51,
                        'I',
                        'D'
                    );

                END IF;


                -------------------------------------------------------------
                -- PARA NO UN:
                -- PRODUCTOSCANTIDADACTUAL = SUMA DE EXISTENCIAS
                -------------------------------------------------------------
                UPDATE PRODUCTOS P

                   SET P.PRODUCTOSCANTIDADACTUAL =
                       NVL(
                           (
                               SELECT
                                   SUM(
                                       NVL(
                                           E.EXISTENCIASCANTIDAD,
                                           0
                                       )
                                   )

                               FROM EXISTENCIAS E

                               WHERE E.EXISTENCIASPRODUCTOCODI =
                                     GRUPO.PRODUC
                           ),
                           0
                       )

                 WHERE P.PRODUCTOSID =
                       v_productos_id;

            END IF;


            -----------------------------------------------------------------
            -- 10. MARCAR COMO PROCESADO TODO EL GRUPO
            -----------------------------------------------------------------
            UPDATE INTEGRACIONEXISTCONTROL C

               SET C.IECDETALLEPROCESADO = 1,
                   C.IECERRORDETALLEMENSAJE = NULL,
                   C.IECFCHULTIMOPROCESO = SYSDATE

             WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

               AND EXISTS
               (
                   SELECT 1

                   FROM TMP_INT_ING R

                   WHERE R.CAMBIOID =
                         C.IECCAMBIOID

                     AND R.PRODUC =
                         GRUPO.PRODUC

                     AND NVL(
                             R.DEPO,
                             CHR(1)
                         ) =
                         GRUPO.DEPO

                     AND NVL(
                             R.UBI,
                             CHR(1)
                         ) =
                         GRUPO.UBI
               );


            COMMIT;


        ---------------------------------------------------------------------
        -- ERROR CONTROLADO DEL GRUPO
        ---------------------------------------------------------------------
        EXCEPTION

            WHEN e_grupo_error THEN

                ROLLBACK TO SP_GRUPO_ING;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       SUBSTR(
                           v_msg,
                           1,
                           1000
                       ),

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_INT_ING R

                       WHERE R.CAMBIOID =
                             C.IECCAMBIOID

                         AND R.PRODUC =
                             GRUPO.PRODUC

                         AND NVL(
                                 R.DEPO,
                                 CHR(1)
                             ) =
                             GRUPO.DEPO

                         AND NVL(
                                 R.UBI,
                                 CHR(1)
                             ) =
                             GRUPO.UBI
                   );


                COMMIT;


            -----------------------------------------------------------------
            -- ERROR INESPERADO DEL GRUPO
            -----------------------------------------------------------------
            WHEN OTHERS THEN

                v_msg :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK TO SP_GRUPO_ING;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_msg,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_INT_ING R

                       WHERE R.CAMBIOID =
                             C.IECCAMBIOID

                         AND R.PRODUC =
                             GRUPO.PRODUC

                         AND NVL(
                                 R.DEPO,
                                 CHR(1)
                             ) =
                             GRUPO.DEPO

                         AND NVL(
                                 R.UBI,
                                 CHR(1)
                             ) =
                             GRUPO.UBI
                   );


                COMMIT;

        END;

    END LOOP;


EXCEPTION

    WHEN OTHERS THEN

        ROLLBACK;
        RAISE;

END; 
/
CREATE PROCEDURE SP_PROC_TRANSF_EXIST_DET_AMER
AS
    v_productos_id         NUMBER;
    v_unidad_medida        VARCHAR2(80);

    v_deposito_origen_id   NUMBER;
    v_deposito_destino_id  NUMBER;

    v_cantidad_transf      NUMBER;
    v_cantidad_disponible  NUMBER;
    v_filas                NUMBER;

    v_cantidad             NUMBER;
    v_msg                  VARCHAR2(1000);

    e_movimiento_error EXCEPTION;

BEGIN

    -------------------------------------------------------------------------
    -- LIMPIAR TEMPORALES DE LA SESION
    -------------------------------------------------------------------------
    DELETE FROM TMP_DET_TRANSF;
    DELETE FROM TMP_PROD_TRANSF;
    DELETE FROM TMP_ALTAS_TRANSF;
    DELETE FROM TMP_BAJAS_TRANSF;
    DELETE FROM TMP_INT_TRANSF;
    DELETE FROM TMP_PEND_TRANSF;

    COMMIT;


    -------------------------------------------------------------------------
    -- 1. PENDIENTES CLASIFICADOS COMO TRANSFERENCIA
    -------------------------------------------------------------------------
    INSERT INTO TMP_PEND_TRANSF
    (
        CAMBIOID
    )
    SELECT
        C.IECCAMBIOID
    FROM INTEGRACIONEXISTCONTROL C
    WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0
      AND C.IECTIPOMOVIMIENTODETALLE = 'T';


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_PEND_TRANSF;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- 2. TRAER INTEGRACIONEXISTENCIAS DESDE SQL SERVER
    -------------------------------------------------------------------------
    INSERT INTO TMP_INT_TRANSF
    (
        CAMBIOID,
        TIPOOPERACION,
        PRODUC,
        DEPO,
        UBI,
        COMPROCODI,
        COMPRONUME,
        COMPROLINEA,
        COMPROFECHA,
        CANTIREALANTERIOR,
        CANTIREALNUEVO
    )
    SELECT
        R."CambioId",
        RTRIM(R."TipoOperacion"),
        R."Produc",
        R."Depo",
        R."Ubi",
        RTRIM(R."ComproCodi"),
        R."ComproNume",
        R."ComproLinea",
        R."ComproFecha",
        R."CantiRealAnterior",
        R."CantiRealNuevo"

    FROM dbo.IntegracionExistencias@MSSQL R

    INNER JOIN TMP_PEND_TRANSF P
        ON P.CAMBIOID = R."CambioId";


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_INT_TRANSF;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- 3. BAJAS DE TRANSFERENCIA
    -------------------------------------------------------------------------
    INSERT INTO TMP_BAJAS_TRANSF
    (
        CAMBIOID,
        PRODUC,
        DEPOORIGEN,
        UBIORIGEN,
        CANTIDADBAJA
    )
    SELECT
        R.CAMBIOID,
        R.PRODUC,

        NVL(
            R.DEPO,
            CHR(1)
        ),

        NVL(
            R.UBI,
            CHR(1)
        ),

        TRUNC
        (
            CASE

                WHEN RTRIM(R.TIPOOPERACION) = 'D'
                THEN
                    NVL(R.CANTIREALANTERIOR, 0)

                WHEN RTRIM(R.TIPOOPERACION) = 'U'
                 AND NVL(R.CANTIREALNUEVO, 0)
                     < NVL(R.CANTIREALANTERIOR, 0)
                THEN
                    NVL(R.CANTIREALANTERIOR, 0)
                    -
                    NVL(R.CANTIREALNUEVO, 0)

                ELSE 0

            END
        )

    FROM TMP_INT_TRANSF R

    WHERE RTRIM(R.TIPOOPERACION) = 'D'

       OR
       (
           RTRIM(R.TIPOOPERACION) = 'U'

           AND NVL(R.CANTIREALNUEVO, 0)
               < NVL(R.CANTIREALANTERIOR, 0)
       );


    -------------------------------------------------------------------------
    -- 4. ALTAS DE TRANSFERENCIA
    -------------------------------------------------------------------------
    INSERT INTO TMP_ALTAS_TRANSF
    (
        CAMBIOID,
        PRODUC,
        DEPODESTINO,
        UBIDESTINO,
        CANTIDADALTA
    )
    SELECT
        R.CAMBIOID,
        R.PRODUC,

        NVL(
            R.DEPO,
            CHR(1)
        ),

        NVL(
            R.UBI,
            CHR(1)
        ),

        TRUNC
        (
            CASE

                WHEN RTRIM(R.TIPOOPERACION) = 'I'
                THEN
                    NVL(R.CANTIREALNUEVO, 0)

                WHEN RTRIM(R.TIPOOPERACION) = 'U'
                 AND NVL(R.CANTIREALNUEVO, 0)
                     > NVL(R.CANTIREALANTERIOR, 0)
                THEN
                    NVL(R.CANTIREALNUEVO, 0)
                    -
                    NVL(R.CANTIREALANTERIOR, 0)

                ELSE 0

            END
        )

    FROM TMP_INT_TRANSF R

    WHERE RTRIM(R.TIPOOPERACION) = 'I'

       OR
       (
           RTRIM(R.TIPOOPERACION) = 'U'

           AND NVL(R.CANTIREALNUEVO, 0)
               > NVL(R.CANTIREALANTERIOR, 0)
       );


    -------------------------------------------------------------------------
    -- 5. PRODUCTOS QUE TIENEN BAJA Y ALTA
    -------------------------------------------------------------------------
    INSERT INTO TMP_PROD_TRANSF
    (
        PRODUC
    )
    SELECT DISTINCT
        B.PRODUC

    FROM TMP_BAJAS_TRANSF B

    INNER JOIN TMP_ALTAS_TRANSF A
        ON A.PRODUC = B.PRODUC;


    SELECT COUNT(*)
      INTO v_cantidad
      FROM TMP_PROD_TRANSF;


    IF v_cantidad = 0 THEN
        COMMIT;
        RETURN;
    END IF;


    -------------------------------------------------------------------------
    -- CONFIRMAR STAGING
    -------------------------------------------------------------------------
    COMMIT;


    -------------------------------------------------------------------------
    -- 6. RECORRER PRODUCTO + ORIGEN + DESTINO
    -------------------------------------------------------------------------
    FOR MOV IN
    (
        SELECT
            B.PRODUC,

            B.DEPOORIGEN,
            B.UBIORIGEN,

            A.DEPODESTINO,
            A.UBIDESTINO,

            B.CANTIDADBAJA,
            A.CANTIDADALTA

        FROM TMP_BAJAS_TRANSF B

        INNER JOIN TMP_ALTAS_TRANSF A
            ON A.PRODUC = B.PRODUC

        INNER JOIN TMP_PROD_TRANSF PT
            ON PT.PRODUC = B.PRODUC

        WHERE B.DEPOORIGEN <> A.DEPODESTINO

        ORDER BY
            B.PRODUC,
            B.DEPOORIGEN,
            A.DEPODESTINO
    )
    LOOP

        BEGIN

            -----------------------------------------------------------------
            -- LIMPIAR IDS DE LA ITERACION ANTERIOR
            -----------------------------------------------------------------
            DELETE FROM TMP_DET_TRANSF;


            SAVEPOINT SP_TRANSF;


            v_productos_id        := NULL;
            v_unidad_medida       := NULL;

            v_deposito_origen_id  := NULL;
            v_deposito_destino_id := NULL;

            v_cantidad_disponible := 0;
            v_filas               := 0;
            v_msg                 := NULL;


            -----------------------------------------------------------------
            -- CANTIDAD REAL DE LA TRANSFERENCIA
            -- MINIMO ENTRE BAJA Y ALTA
            -----------------------------------------------------------------
            v_cantidad_transf :=
                LEAST
                (
                    NVL(MOV.CANTIDADBAJA, 0),
                    NVL(MOV.CANTIDADALTA, 0)
                );


            IF NVL(v_cantidad_transf, 0) <= 0 THEN

                v_msg :=
                    'CantidadTransferencia calculada <= 0';

                RAISE e_movimiento_error;

            END IF;


            -----------------------------------------------------------------
            -- 7. PRODUCTO LOCAL + UNIDAD DE MEDIDA
            -----------------------------------------------------------------
            BEGIN

                SELECT
                    X.PRODUCTOSID,
                    X.UNIDADMEDIDA

                INTO
                    v_productos_id,
                    v_unidad_medida

                FROM
                (
                    SELECT
                        P.PRODUCTOSID,

                        UM.UNIDADESMEDIDACODIGO
                            AS UNIDADMEDIDA

                    FROM PRODUCTOS P

                    LEFT JOIN UNIDADESMEDIDA UM
                        ON UM.UNIDADESMEDIDAID =
                           P.UNIDADESMEDIDAID

                    WHERE P.PRODUCTOSCODIGO =
                          MOV.PRODUC
                ) X

                WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro ProductosId local para transferencia';

                    RAISE e_movimiento_error;

            END;


            -----------------------------------------------------------------
            -- 8. DEPOSITO ORIGEN
            -----------------------------------------------------------------
            BEGIN

                SELECT X.DEPOSITOSID

                  INTO v_deposito_origen_id

                  FROM
                  (
                      SELECT
                          D.DEPOSITOSID

                      FROM DEPOSITOS D

                      WHERE D.DEPOSITOSCODIGO =
                            NULLIF(
                                MOV.DEPOORIGEN,
                                CHR(1)
                            )
                  ) X

                 WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro DepositosId origen local';

                    RAISE e_movimiento_error;

            END;


            -----------------------------------------------------------------
            -- 9. DEPOSITO DESTINO
            -----------------------------------------------------------------
            BEGIN

                SELECT X.DEPOSITOSID

                  INTO v_deposito_destino_id

                  FROM
                  (
                      SELECT
                          D.DEPOSITOSID

                      FROM DEPOSITOS D

                      WHERE D.DEPOSITOSCODIGO =
                            NULLIF(
                                MOV.DEPODESTINO,
                                CHR(1)
                            )
                  ) X

                 WHERE ROWNUM = 1;


            EXCEPTION

                WHEN NO_DATA_FOUND THEN

                    v_msg :=
                        'No se encontro DepositosId destino local';

                    RAISE e_movimiento_error;

            END;


            -----------------------------------------------------------------
            -- 10. PRODUCTOS POR UNIDAD
            -----------------------------------------------------------------
            IF UPPER(TRIM(v_unidad_medida)) = 'UN' THEN


                -------------------------------------------------------------
                -- CANTIDAD DISPONIBLE EN ORIGEN
                -------------------------------------------------------------
                SELECT COUNT(*)

                  INTO v_cantidad_disponible

                  FROM EXISTENCIASDETALLE ED

                 WHERE ED.PRODUCTOSID =
                       v_productos_id

                   AND ED.DEPOSITOSID =
                       v_deposito_origen_id

                   AND ED.EXISTENCIASDETALLEESTADO =
                       'D'

                   AND ED.ORGANIGRAMAID =
                       51;


                IF NVL(v_cantidad_disponible, 0)
                   < v_cantidad_transf
                THEN

                    v_msg :=
                        'Transferencia mayor a detalles disponibles';

                    RAISE e_movimiento_error;

                END IF;


                -------------------------------------------------------------
                -- TOMAR LAS PRIMERAS N UNIDADES
                -------------------------------------------------------------
                INSERT INTO TMP_DET_TRANSF
                (
                    EXISTENCIASDETALLEID
                )
                SELECT
                    EXISTENCIASDETALLEID

                FROM
                (
                    SELECT
                        ED.EXISTENCIASDETALLEID

                    FROM EXISTENCIASDETALLE ED

                    WHERE ED.PRODUCTOSID =
                          v_productos_id

                      AND ED.DEPOSITOSID =
                          v_deposito_origen_id

                      AND ED.EXISTENCIASDETALLEESTADO =
                          'D'

                      AND ED.ORGANIGRAMAID =
                          51

                    ORDER BY
                        ED.EXISTENCIASDETALLEID
                )

                WHERE ROWNUM <=
                      v_cantidad_transf;


                -------------------------------------------------------------
                -- MOVER LAS UNIDADES AL DEPOSITO DESTINO
                -------------------------------------------------------------
                UPDATE EXISTENCIASDETALLE ED

                   SET ED.DEPOSITOSID =
                       v_deposito_destino_id,

                       ED.EXISTENCIASDETALLEESTADO =
                       'D',

                       ED.ORGANIGRAMAID =
                       51

                 WHERE EXISTS
                 (
                     SELECT 1

                     FROM TMP_DET_TRANSF T

                     WHERE T.EXISTENCIASDETALLEID =
                           ED.EXISTENCIASDETALLEID
                 );


                v_filas := SQL%ROWCOUNT;


                IF v_filas <> v_cantidad_transf THEN

                    v_msg :=
                        'Se esperaban mover '
                        || TO_CHAR(v_cantidad_transf)
                        || ' filas y se movieron '
                        || TO_CHAR(v_filas);

                    RAISE e_movimiento_error;

                END IF;


            -----------------------------------------------------------------
            -- 11. PRODUCTOS NO UNITARIOS
            -----------------------------------------------------------------
            ELSE


                -------------------------------------------------------------
                -- TOMAR UNA FILA REPRESENTATIVA
                -------------------------------------------------------------
                INSERT INTO TMP_DET_TRANSF
                (
                    EXISTENCIASDETALLEID
                )
                SELECT
                    EXISTENCIASDETALLEID

                FROM
                (
                    SELECT
                        ED.EXISTENCIASDETALLEID

                    FROM EXISTENCIASDETALLE ED

                    WHERE ED.PRODUCTOSID =
                          v_productos_id

                      AND ED.DEPOSITOSID =
                          v_deposito_origen_id

                      AND ED.EXISTENCIASDETALLEESTADO =
                          'D'

                      AND ED.ORGANIGRAMAID =
                          51

                    ORDER BY
                        ED.EXISTENCIASDETALLEID
                )

                WHERE ROWNUM = 1;


                -------------------------------------------------------------
                -- MOVER FILA REPRESENTATIVA
                -------------------------------------------------------------
                UPDATE EXISTENCIASDETALLE ED

                   SET ED.DEPOSITOSID =
                       v_deposito_destino_id,

                       ED.EXISTENCIASDETALLEESTADO =
                       'D',

                       ED.ORGANIGRAMAID =
                       51

                 WHERE EXISTS
                 (
                     SELECT 1

                     FROM TMP_DET_TRANSF T

                     WHERE T.EXISTENCIASDETALLEID =
                           ED.EXISTENCIASDETALLEID
                 );


                v_filas := SQL%ROWCOUNT;


                IF v_filas <> 1 THEN

                    v_msg :=
                        'No se encontro fila representativa no-UN para transferencia';

                    RAISE e_movimiento_error;

                END IF;

            END IF;


            -----------------------------------------------------------------
            -- 12. HISTORICO DE DEPOSITOS
            -----------------------------------------------------------------
            INSERT INTO DEPOSITOSHISTORICO
            (
                EXISTENCIASDETALLEID,
                ST_DEPOSITOANTERIORID,
                ST_DEPOSITONUEVOID,
                DEPOSITOSHISTORICOFCHALTA
            )
            SELECT
                T.EXISTENCIASDETALLEID,
                v_deposito_origen_id,
                v_deposito_destino_id,
                SYSDATE

            FROM TMP_DET_TRANSF T;


            -----------------------------------------------------------------
            -- 13. MARCAR COMO PROCESADAS TODAS LAS FILAS T DEL PRODUCTO
            -----------------------------------------------------------------
            UPDATE INTEGRACIONEXISTCONTROL C

               SET C.IECDETALLEPROCESADO = 1,
                   C.IECERRORDETALLEMENSAJE = NULL,
                   C.IECFCHULTIMOPROCESO = SYSDATE

             WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

               AND C.IECTIPOMOVIMIENTODETALLE = 'T'

               AND EXISTS
               (
                   SELECT 1

                   FROM TMP_INT_TRANSF R

                   WHERE R.CAMBIOID =
                         C.IECCAMBIOID

                     AND R.PRODUC =
                         MOV.PRODUC
               );


            COMMIT;


        ---------------------------------------------------------------------
        -- ERROR CONTROLADO DEL MOVIMIENTO
        ---------------------------------------------------------------------
        EXCEPTION

            WHEN e_movimiento_error THEN

                ROLLBACK TO SP_TRANSF;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       SUBSTR(
                           v_msg,
                           1,
                           1000
                       ),

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND C.IECTIPOMOVIMIENTODETALLE = 'T'

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_INT_TRANSF R

                       WHERE R.CAMBIOID =
                             C.IECCAMBIOID

                         AND R.PRODUC =
                             MOV.PRODUC
                   );


                COMMIT;


            -----------------------------------------------------------------
            -- ERROR INESPERADO
            -----------------------------------------------------------------
            WHEN OTHERS THEN

                v_msg :=
                    SUBSTR(
                        SQLERRM,
                        1,
                        1000
                    );


                ROLLBACK TO SP_TRANSF;


                UPDATE INTEGRACIONEXISTCONTROL C

                   SET C.IECERRORDETALLEMENSAJE =
                       v_msg,

                       C.IECFCHULTIMOPROCESO =
                       SYSDATE

                 WHERE NVL(C.IECDETALLEPROCESADO, 0) = 0

                   AND C.IECTIPOMOVIMIENTODETALLE = 'T'

                   AND EXISTS
                   (
                       SELECT 1

                       FROM TMP_INT_TRANSF R

                       WHERE R.CAMBIOID =
                             C.IECCAMBIOID

                         AND R.PRODUC =
                             MOV.PRODUC
                   );


                COMMIT;

        END;

    END LOOP;


EXCEPTION

    WHEN OTHERS THEN

        ROLLBACK;
        RAISE;

END; 
/
CREATE PROCEDURE SP_REGISTRAR_EXIS_DET_MOV
(
    p_exist_det_id       IN NUMBER,
    p_tipo               IN VARCHAR2,

    p_estado_ant         IN VARCHAR2 DEFAULT NULL,
    p_estado_nvo         IN VARCHAR2,

    p_depo_ant_id        IN NUMBER DEFAULT NULL,
    p_depo_nvo_id        IN NUMBER DEFAULT NULL,

    p_organig_ant_id     IN NUMBER DEFAULT NULL,
    p_organig_nvo_id     IN NUMBER DEFAULT NULL,

    p_fuente_ant_id      IN NUMBER DEFAULT NULL,
    p_fuente_nva_id      IN NUMBER DEFAULT NULL,

    p_origen             IN VARCHAR2,

    p_cambio_id          IN NUMBER DEFAULT 0,
    p_devol_unidad_id    IN NUMBER DEFAULT 0,

    p_observaciones      IN VARCHAR2 DEFAULT NULL
)
AS
    v_deposito_sin_deposito NUMBER;
    v_organigrama_no_asig    NUMBER;
    v_fuente_no_asig         NUMBER;

    v_depo_ant_id            NUMBER;
    v_depo_nvo_id            NUMBER;

    v_organig_ant_id         NUMBER;
    v_organig_nvo_id         NUMBER;

    v_fuente_ant_id          NUMBER;
    v_fuente_nva_id          NUMBER;

    v_cambio_id              NUMBER;
    v_devol_unidad_id        NUMBER;

    v_existe                 NUMBER;

BEGIN

    -------------------------------------------------------------------------
    -- 1. OBTENER PARAMETROS DEL SISTEMA
    -------------------------------------------------------------------------
    SELECT
        MAX(
            CASE
                WHEN PARAMETROSSISTEMACODIGO = 'DEPOSITO_SIN_DEPOSITO'
                THEN PARAMETROSSISTEMAVALORINT
            END
        ),

        MAX(
            CASE
                WHEN PARAMETROSSISTEMACODIGO = 'ORGANIGRAMA_NO_ASIGNADO'
                THEN PARAMETROSSISTEMAVALORINT
            END
        ),

        MAX(
            CASE
                WHEN PARAMETROSSISTEMACODIGO = 'FUENTE_NO_ASIGNADA'
                THEN PARAMETROSSISTEMAVALORINT
            END
        )

    INTO
        v_deposito_sin_deposito,
        v_organigrama_no_asig,
        v_fuente_no_asig

    FROM GXCONTABLE.PARAMETROSSISTEMA

    WHERE PARAMETROSSISTEMACODIGO IN
    (
        'DEPOSITO_SIN_DEPOSITO',
        'ORGANIGRAMA_NO_ASIGNADO',
        'FUENTE_NO_ASIGNADA'
    );


    -------------------------------------------------------------------------
    -- 2. VALIDAR PARAMETROS OBLIGATORIOS
    -------------------------------------------------------------------------
    IF v_deposito_sin_deposito IS NULL
       OR v_organigrama_no_asig IS NULL
       OR v_fuente_no_asig IS NULL
    THEN

        RAISE_APPLICATION_ERROR
        (
            -20001,
            'No se encontraron los parametros obligatorios del sistema para registrar movimientos de existencias.'
        );

    END IF;


    -------------------------------------------------------------------------
    -- 3. COMPLETAR VALORES POR DEFECTO
    -------------------------------------------------------------------------
    v_cambio_id :=
        NVL(p_cambio_id, 0);

    v_devol_unidad_id :=
        NVL(p_devol_unidad_id, 0);


    v_depo_ant_id :=
        NVL(
            p_depo_ant_id,
            v_deposito_sin_deposito
        );

    v_depo_nvo_id :=
        NVL(
            p_depo_nvo_id,
            v_deposito_sin_deposito
        );


    v_organig_ant_id :=
        NVL(
            p_organig_ant_id,
            v_organigrama_no_asig
        );

    v_organig_nvo_id :=
        NVL(
            p_organig_nvo_id,
            v_organigrama_no_asig
        );


    v_fuente_ant_id :=
        NVL(
            p_fuente_ant_id,
            v_fuente_no_asig
        );

    v_fuente_nva_id :=
        NVL(
            p_fuente_nva_id,
            v_fuente_no_asig
        );


    -------------------------------------------------------------------------
    -- 4. EVITAR DUPLICADOS CUANDO VIENE DE UN CAMBIO DE INTEGRACION
    -------------------------------------------------------------------------
    IF v_cambio_id <> 0 THEN

        SELECT COUNT(*)
        INTO v_existe
        FROM GXCONTABLE.EXISDETMOV
        WHERE EXISDETMOVCAMBIOID = v_cambio_id
          AND EXISTENCIASDETALLEID = p_exist_det_id
          AND EXISDETMOVTIPO = p_tipo;


        IF v_existe > 0 THEN
            RETURN;
        END IF;

    END IF;


    -------------------------------------------------------------------------
    -- 5. REGISTRAR MOVIMIENTO
    -------------------------------------------------------------------------
    INSERT INTO GXCONTABLE.EXISDETMOV
    (
        EXISDETMOVTIPO,
        EXISDETMOVFCHREGISTRO,
        EXISDETMOVOBSERVACIONES,
        EXISDETMOVORIGEN,

        EXISTENCIASDETALLEID,

        EXISDETMOVESTADOANTERIOR,
        EXISDETMOVESTADONUEVO,

        EXISDETMOVCAMBIOID,

        EXISDETMOVDEPOANTERIORID,
        EXISDETMOVDEPONUEVOID,

        EXISDETMOVORGANIGANTID,
        EXISDETMOVORGANIGNVOID,

        EXISDETMOVFUENTEANTID,
        EXISDETMOVFUENTENVAID,

        EXISDETMOVDEVOLUCIONUNIDADID
    )
    VALUES
    (
        p_tipo,
        SYSDATE,
        p_observaciones,
        p_origen,

        p_exist_det_id,

        p_estado_ant,
        p_estado_nvo,

        v_cambio_id,

        v_depo_ant_id,
        v_depo_nvo_id,

        v_organig_ant_id,
        v_organig_nvo_id,

        v_fuente_ant_id,
        v_fuente_nva_id,

        v_devol_unidad_id
    );

END; 
/
